<template><el-card shadow="never"><template #header>消息发布</template><el-form :model="form" label-width="110px" style="max-width:700px"><el-form-item label="连接"><el-select v-model="form.connectionCode"><el-option v-for="item in connections" :key="item.connectionCode" :label="item.name" :value="item.connectionCode"/></el-select></el-form-item><el-form-item label="主题"><el-input v-model="form.topic" placeholder="xn/xn_device/设备ID/command"/></el-form-item><el-form-item label="Payload"><el-input v-model="form.payload" type="textarea" :rows="10"/></el-form-item><el-form-item label="QoS"><el-select v-model="form.qos"><el-option v-for="item in [0,1,2]" :key="item" :label="String(item)" :value="item"/></el-select></el-form-item><el-form-item label="保留消息"><el-switch v-model="form.retain"/></el-form-item><el-button type="primary" @click="publish">发布</el-button></el-form></el-card></template>
<script setup lang="ts">import { onMounted, reactive, ref } from 'vue'; import { ElMessage } from 'element-plus'; import http from '../../api/http'; const connections=ref<any[]>([]); const form=reactive({connectionCode:'',topic:'',payload:'{}',qos:0 as 0|1|2,retain:false}); onMounted(async()=>{const {data}=await http.get('/mqtt/connections');connections.value=data;if(data[0])form.connectionCode=data[0].connectionCode;}); async function publish(){let payload:unknown;try{payload=JSON.parse(form.payload);}catch{payload=form.payload;}try{await http.post('/mqtt/publish',{...form,payload});ElMessage.success('发布成功');}catch(e:any){ElMessage.error(e.response?.data?.message||'发布失败');}}</script>
